function cw2_json(array $data,int $status=200):void{http_response_code($status);echo json_encode($data,JSON_UNESCAPED_SLASHES);exit;}
function cw2_body():array{$data=json_decode((string)file_get_contents('php://input'),true);return is_array($data)?$data:[];}
function cw2_user():array{$u=current_user();return ['id'=>(int)($u['id']??0),'name'=>(string)($u['name']??'Unknown')];}
function cw2_audit(PDO $pdo,string $type,int $id,string $action,$before=null,$after=null,?string $reason=null):void{$u=cw2_user();$st=$pdo->prepare('INSERT INTO cw_cost_audit_events(entity_type,entity_id,action_key,before_json,after_json,reason,actor_id,actor_name) VALUES(?,?,?,?,?,?,?,?)');$st->execute([$type,$id,$action,$before===null?null:json_encode($before,JSON_UNESCAPED_SLASHES),$after===null?null:json_encode($after,JSON_UNESCAPED_SLASHES),$reason,$u['id'],$u['name']]);}
function cw2_shipment(PDO $pdo,int $id,bool $lock=false):array{$st=$pdo->prepare('SELECT * FROM cw_shipments WHERE id=?'.($lock?' FOR UPDATE':''));$st->execute([$id]);$r=$st->fetch();if(!$r)throw new RuntimeException('Shipment not found.');return $r;}
function cw2_draft(PDO $pdo,int $shipmentId,bool $lock=false):?array{$sql="SELECT v.* FROM cw_landed_calculation_versions v JOIN cw_landed_calculations c ON c.id=v.calculation_id WHERE c.shipment_id=? AND v.status='draft' ORDER BY v.version DESC LIMIT 1".($lock?' FOR UPDATE':'');$st=$pdo->prepare($sql);$st->execute([$shipmentId]);return $st->fetch()?:null;}
function cw2_latest_version(PDO $pdo,int $shipmentId):?array{$st=$pdo->prepare('SELECT v.* FROM cw_landed_calculation_versions v JOIN cw_landed_calculations c ON c.id=v.calculation_id WHERE c.shipment_id=? ORDER BY v.version DESC LIMIT 1');$st->execute([$shipmentId]);return $st->fetch()?:null;}
function cw2_money(string $v):int{return (int)round((float)$v*100,0,PHP_ROUND_HALF_UP);}

